import java.nio.charset.StandardCharsets;
import java.util.*;

public class MaskowanieProbki {
    static String maskuj(String pole, String wartosc) {
        if (pole.equals("email") && wartosc.contains("@")) {
            return wartosc.charAt(0) + "***" + wartosc.substring(wartosc.indexOf('@'));
        }
        if (pole.equals("phone") && wartosc.length() > 3) {
            return "*".repeat(wartosc.length() - 3) + wartosc.substring(wartosc.length() - 3);
        }
        return "<" + wartosc.getBytes(StandardCharsets.UTF_8).length + " B>";
    }

    public static void main(String[] args) {
        Map<String, String> hash = new LinkedHashMap<>();
        hash.put("name", "Zażółć");
        hash.put("email", "anna@example.test");
        hash.put("phone", "48600100200");
        hash.forEach((p, w) -> System.out.println(p + " = " + maskuj(p, w)));
    }
}
// name = <10 B>
// email = a***@example.test
// phone = ********200
Karta próbki pokazuje strukturę i rozmiary bez ujawniania danych osobowych w notatkach migracyjnych.
